SELECT p.gender, p.age, a.admission_type_id, d.diagnosis_id, COUNT(*) AS event_count, CAST(COUNT(*) filter (WHERE l.value_num > 1.5) AS FLOAT) / NULLIF(COUNT(*), 0) AS high_troponin_ratio, AVG(l.value_num) AS avg_troponin, MEDIAN(l.value_num) AS median_troponin, (percentile_cont(0.75) within GROUP (ORDER BY l.value_num) - percentile_cont(0.25) within GROUP (ORDER BY l.value_num)) AS interquartile_range FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN labevents l ON a.subject_id = l.subject_id AND a.hadm_id = l.hadm_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND p.age BETWEEN 79 AND 89 AND a.admission_type_id = 25 AND d.diagnosis_id = 757071 AND l.value_num > 1.5 GROUP BY p.gender, p.age, a.admission_type_id, d.diagnosis_id ORDER BY event_count DESC NULLS LAST;